// Code generated by ffi-eject for -with-errno; DO NOT EDIT.

//go:build (darwin || linux) && (amd64 || arm64)

package ffi_test

import (
	"syscall"
	"testing"

	ffi "github.com/tmc/lib/nvidia/internal/ffi"
)

func TestCallErrno(t *testing.T) {
	fn := buildSym(t, srcSetErrno, "set_errno")
	// EIO then 0, so a slot that kept the previous call's errno is caught too.
	for _, want := range []syscall.Errno{syscall.EIO, 0} {
		var args [ffi.MaxArgs]uintptr
		args[0] = uintptr(want)
		r1, _, errno := ffi.CallErrno(fn, 1, &args, 0)
		if int64(r1) != -1 {
			t.Fatalf("set_errno(%d) = %d, want -1", want, int64(r1))
		}
		if got := syscall.Errno(errno); got != want {
			t.Errorf("set_errno(%d): errno = %d, want %d", want, got, want)
		}
	}
}

func TestCallErrno_Allocs(t *testing.T) {
	fn := buildSym(t, srcSetErrno, "set_errno")
	var args [ffi.MaxArgs]uintptr
	args[0] = uintptr(syscall.EIO)
	if n := testing.AllocsPerRun(100, func() { ffi.CallErrno(fn, 1, &args, 0) }); n != 0 {
		t.Errorf("CallErrno allocates %v times per call, want 0", n)
	}
}
